// ─── Extract dominant colors from uploaded image via canvas ───────────────────
function extractColorsFromImage(dataUrl) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement("canvas");
      const SIZE = 80; // downsample for speed
      canvas.width = SIZE; canvas.height = SIZE;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, SIZE, SIZE);
      const data = ctx.getImageData(0, 0, SIZE, SIZE).data;

      // Bucket colors into 32-step increments to group similar shades
      const buckets = {};
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i], g = data[i+1], b = data[i+2], a = data[i+3];
        if (a < 80) continue; // skip transparent pixels
        // Skip near-black and near-white (background colors, not brand colors)
        const brightness = (r + g + b) / 3;
        if (brightness < 25 || brightness > 230) continue;
        const key = `${Math.round(r/32)*32},${Math.round(g/32)*32},${Math.round(b/32)*32}`;
        buckets[key] = (buckets[key] || 0) + 1;
      }

      // Sort by frequency, take top 8
      const sorted = Object.entries(buckets)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 8)
        .map(([key]) => {
          const [r, g, b] = key.split(",").map(Number);
          return "#" + [r,g,b].map(v => Math.min(255,v).toString(16).padStart(2,"0")).join("");
        });

      resolve(sorted);
    };
    img.onerror = () => resolve([]);
    img.src = dataUrl;
  });
}



