// ─── Claude API call ────────────────────────────────────────────────────────────
async function callClaude(prompt, submissionId) {
  const res = await fetch(`/api/claude/${submissionId}`, {
    method:"POST",
    headers:{ "Content-Type":"application/json" },
    body: JSON.stringify({
      model:"claude-sonnet-4-20250514",
      max_tokens:4000,
      messages:[{ role:"user", content:prompt }]
    })
  });
  const data = await res.json();
  if (data.error) throw new Error(data.error.message || "API error");
  return data.content?.[0]?.text || "";
}

function extractJSON(raw) {
  // Strategy 1: direct parse
  try { return JSON.parse(raw.trim()); } catch(e) {}
  // Strategy 2: strip markdown fences then parse
  const s1 = raw.replace(/^```(?:json)?\s*/m, "").replace(/\s*```$/m, "").trim();
  try { return JSON.parse(s1); } catch(e) {}
  // Strategy 3: extract first { ... } block
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch(e) {} }
  return null;
}

async function generateAllContent(biz, submissionId) {
  const svcList = biz.services.slice(0, 8).join(", ");
  const svcKeys = biz.services.slice(0, 8)
    .map(s => `    "${s}": "2-3 sentences about this specific ${s} service in ${biz.city}, ${biz.state}. Focus on customer benefits, results, and local expertise. Naturally include the city name once."`)
    .join(",\n");
  const certList = biz.certs && biz.certs.length > 0 ? biz.certs.join(", ") : "none listed";
  const serviceAreasList = biz.serviceAreas ? biz.serviceAreas : `${biz.city} and surrounding areas`;
  const fullAddress = biz.address ? `${biz.address}, ${biz.city}, ${biz.state} ${biz.zip || ""}`.trim() : `${biz.city}, ${biz.state}`;

  const prompt = `Generate website copy for this home service business. Output a single raw JSON object only — no markdown, no explanation.

Business name: ${biz.name}
Service type: ${biz.type}
Tagline: ${biz.tagline || ""}
City, State: ${biz.city}, ${biz.state}
Full address: ${fullAddress}
Years in business: ${biz.years || "several years"}
Description: ${biz.description}
Services offered: ${svcList}
Certifications & credentials: ${certList}
Service areas: ${serviceAreasList}
Emergency service: ${biz.emergency ? "yes — available 24/7" : "no"}
Financing available: ${biz.financing ? "yes" : "no"}
Warranty: ${biz.warranty || "standard workmanship warranty"}

Required JSON structure:
{
  "heroHeadline": "Complete 4-7 word ALL CAPS headline that includes the trade (e.g. ROOFING THAT LASTS A LIFETIME). Never use the business name. Must make sense alone.",
  "heroSub": "one compelling sentence under 12 words explaining why customers choose them",
  "aboutParagraph": "two short paragraphs (newline between them), warm and local, 80-100 words total — naturally weave in certifications, years, and city name",
  "serviceDescriptions": {
${svcKeys}
  },
  "faq": [
    {"q": "Are you licensed and insured?", "a": "specific two-sentence answer referencing certifications if listed"},
    {"q": "Do you offer free estimates?", "a": "specific two-sentence answer"},
    {"q": "How quickly can you respond?", "a": "specific two-sentence answer mentioning 24/7 emergency if applicable"},
    {"q": "What areas do you serve?", "a": "specific two-sentence answer listing the service areas provided"},
    {"q": "What warranty do you provide on your work?", "a": "specific two-sentence answer about warranty and quality guarantee"}
  ],
  "seoTitle": "under 60 chars: Business Name | #1 Type in City, ST",
  "seoDesc": "150-160 chars for Google including city, type, and key benefit",
  "seoKeywords": "10 comma-separated local search keywords including city and service type",
  "ctaHeadline": "urgent call-to-action headline, max 7 words",
  "trustStatement": "one sentence mentioning license/certifications, years of experience, and guarantee"
}`;

  console.log('Sending prompt to Claude API...');
  const raw = await callClaude(prompt, submissionId);
  console.log('Raw AI response:', raw.substring(0, 500));
  
  const result = extractJSON(raw);

  if (!result) {
    throw new Error("AI returned an unparseable response. Please try again.");
  }

  console.log('Parsed AI result:', result);
  console.log('Service descriptions from AI:', result.serviceDescriptions);

  // Ensure all required fields exist with fallbacks
  const finalResult = {
    heroHeadline: result.heroHeadline || `${biz.name.toUpperCase()}`,
    heroSub: result.heroSub || biz.tagline || `Professional ${biz.type} services in ${biz.city}`,
    aboutParagraph: result.aboutParagraph || biz.description,
    serviceDescriptions: result.serviceDescriptions || {},
    faq: result.faq || [
      {q: "Are you licensed and insured?", a: `Yes, ${biz.name} is fully licensed and insured in ${biz.state}.`},
      {q: "Do you offer free estimates?", a: "Absolutely. We provide free, no-obligation estimates for all projects."},
      {q: "How quickly can you respond?", a: `We typically respond within 24 hours.${biz.emergency ? " For emergencies, we're available 24/7." : ""}`},
      {q: "What areas do you serve?", a: `We proudly serve ${biz.city} and surrounding areas in ${biz.state}.`}
    ],
    seoTitle: result.seoTitle || `${biz.name} | ${biz.type} in ${biz.city}`,
    seoDesc: result.seoDesc || biz.description.slice(0, 160),
    seoKeywords: result.seoKeywords || `${biz.type}, ${biz.city}, ${biz.state}`,
    ctaHeadline: result.ctaHeadline || "Ready to Get Started?",
    trustStatement: result.trustStatement || `Licensed and insured ${biz.type.toLowerCase()} contractor serving ${biz.city}.`
  };

  // Fill in missing service descriptions
  console.log('Filling service descriptions...');
  biz.services.forEach(s => {
    if (!finalResult.serviceDescriptions[s] || finalResult.serviceDescriptions[s] === '') {
      console.log(`Adding fallback for service: ${s}`);
      finalResult.serviceDescriptions[s] = `Expert ${s.toLowerCase()} services delivered with precision, quality materials, and a written satisfaction guarantee.`;
    }
  });

  console.log('Final AI content:', finalResult);
  return finalResult;
}

