function Btn({ children, onClick, disabled, outline, style={} }) {
  const base = {
    display:"inline-flex", alignItems:"center", gap:"7px",
    padding:"12px 26px",
    background: outline ? "transparent" : disabled ? "#1a1a1a" : Y,
    color: outline ? "#777" : disabled ? "#444" : BK,
    border: outline ? "1px solid #2a2a2a" : "none",
    borderRadius:"3px", cursor: disabled ? "not-allowed" : "pointer",
    fontFamily:"'Bebas Neue',sans-serif", fontSize:"1.1rem", letterSpacing:"2px",
    transition:"all .2s",
    boxShadow: !outline && !disabled ? "0 4px 16px rgba(240,196,25,.25)" : "none",
    ...style
  };
  return (
    <button style={base} onClick={onClick} disabled={disabled}
      onMouseEnter={e=>{ if(!disabled){ if(outline){e.currentTarget.style.borderColor=Y;e.currentTarget.style.color=Y;}else{e.currentTarget.style.transform="translateY(-2px)";e.currentTarget.style.boxShadow="0 8px 26px rgba(240,196,25,.4)";} }}}
      onMouseLeave={e=>{ e.currentTarget.style.transform=""; e.currentTarget.style.boxShadow=(!outline&&!disabled)?"0 4px 16px rgba(240,196,25,.25)":"none"; if(outline){e.currentTarget.style.borderColor="#2a2a2a";e.currentTarget.style.color="#777";} }}>
      {children}
    </button>
  );
}

function In({ value, onChange, placeholder, type="text", maxLength, style={} }) {
  const [f,setF]=useState(false);
  return (
    <input type={type} value={value} onChange={onChange} placeholder={placeholder} maxLength={maxLength}
      onFocus={()=>setF(true)} onBlur={()=>setF(false)}
      style={{ width:"100%", padding:"10px 12px", background:"#fff", color:"#111",
        border:`1.5px solid ${f?Y:"#d1d5db"}`, borderRadius:"3px",
        fontSize:"1rem", fontFamily:"inherit", outline:"none", transition:"border-color .15s",
        boxShadow: f?`0 0 0 3px rgba(240,196,25,.1)`:"none", boxSizing:"border-box", ...style }} />
  );
}

function Ta({ value, onChange, placeholder, rows=3, maxLength }) {
  const [f,setF]=useState(false);
  return (
    <textarea value={value} onChange={onChange} placeholder={placeholder} rows={rows} maxLength={maxLength}
      onFocus={()=>setF(true)} onBlur={()=>setF(false)}
      style={{ width:"100%", padding:"10px 12px", background:"#fff", color:"#111",
        border:`1.5px solid ${f?Y:"#d1d5db"}`, borderRadius:"3px",
        fontSize:"1rem", fontFamily:"inherit", outline:"none", resize:"vertical",
        transition:"border-color .15s", boxShadow:f?`0 0 0 3px rgba(240,196,25,.1)`:"none",
        boxSizing:"border-box" }} />
  );
}

function Chip({ label, active, onClick, disabled=false }) {
  return (
    <div onClick={disabled?null:onClick} style={{
      display:"flex", alignItems:"center", gap:"8px",
      padding:"8px 12px",
      background: active ? Y : "#fff",
      color: active ? BK : "#555",
      border: `1.5px solid ${active ? Y : "#d1d5db"}`,
      borderRadius:"3px", cursor: disabled ? "default" : "pointer",
      fontSize:".83rem", fontWeight: active ? 700 : 500,
      transition:"all .12s", userSelect:"none",
    }}
    onMouseEnter={e=>{ if(!active&&!disabled){ e.currentTarget.style.borderColor="#aaa"; e.currentTarget.style.color="#111"; }}}
    onMouseLeave={e=>{ if(!active&&!disabled){ e.currentTarget.style.borderColor="#d1d5db"; e.currentTarget.style.color="#555"; }}}>
      <span style={{
        width:"16px", height:"16px", borderRadius:"2px", flexShrink:0,
        background: active ? BK : "transparent",
        border:`2px solid ${active ? BK : "#ccc"}`,
        display:"flex", alignItems:"center", justifyContent:"center",
        color: active ? Y : "transparent", fontSize:"9px", transition:"all .12s",
      }}>{active && "✓"}</span>
      {label}
    </div>
  );
}

function Drop({ id, label, required, hint, preview, previews, onFile, onRemove, multiple, sublabel }) {
  const [drag, setDrag] = useState(false);
  const hasContent = preview || (previews && previews.length > 0);
  return (
    <div style={{marginBottom:"18px"}}>
      <label style={{display:"block", fontSize:".72rem", fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, letterSpacing:"2.5px", textTransform:"uppercase", color:"#555", marginBottom:"5px"}}>
        {label}{required && <span style={{color:"#e11d48",marginLeft:"4px"}}>*</span>}
      </label>
      {hint && <p style={{fontSize:".75rem", color:"#aaa", marginBottom:"6px"}}>{hint}</p>}
      <input type="file" id={id} accept="image/*" multiple={multiple} onChange={onFile} style={{display:"none"}} />
      <label htmlFor={id}
        onDragOver={e=>{e.preventDefault();setDrag(true);}}
        onDragLeave={()=>setDrag(false)}
        onDrop={e=>{e.preventDefault();setDrag(false);onFile({target:{files:e.dataTransfer.files}});}}
        style={{display:"block",cursor:"pointer"}}>
        <div style={{
          border:`2px dashed ${drag ? Y : hasContent ? Y+"88" : "#d1d5db"}`,
          borderRadius:"4px", padding:"22px 16px", textAlign:"center",
          background: drag ? "rgba(240,196,25,.04)" : hasContent ? "rgba(240,196,25,.02)" : "#fafafa",
          transition:"all .2s",
        }}>
          {preview ? (
            <div>
              <img src={preview} alt="" style={{maxHeight:"120px", borderRadius:"3px", margin:"0 auto 8px", boxShadow:"0 4px 16px rgba(0,0,0,.15)"}} />
              <p style={{color:Y, fontSize:".75rem", fontFamily:"'Barlow Condensed',sans-serif", fontWeight:700, letterSpacing:"2px"}}>UPLOADED — CLICK TO REPLACE</p>
            </div>
          ) : (
            <div>
              <div style={{color:"#ccc", marginBottom:"8px"}}>{multiple ? Icons.img : Icons.up}</div>
              <p style={{color:"#666", fontFamily:"'Barlow Condensed',sans-serif", fontWeight:600, letterSpacing:"1px", fontSize:".85rem", marginBottom:"3px"}}>
                {drag ? "Drop to Upload" : sublabel || "Click or Drag to Upload"}
              </p>
              <p style={{color:"#bbb", fontSize:".75rem"}}>{multiple ? "Up to 8 images · 10MB each" : "PNG, JPG, SVG · Max 10MB"}</p>
            </div>
          )}
        </div>
      </label>
      {previews && previews.length > 0 && (
        <div style={{display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(90px,1fr))", gap:"6px", marginTop:"8px"}}>
          {previews.map((src,i)=>(
            <div key={i} style={{position:"relative", aspectRatio:"1", borderRadius:"3px", overflow:"hidden", border:"1px solid #e5e7eb"}}>
              <img src={src} alt="" style={{width:"100%", height:"100%", objectFit:"cover"}} />
              <button onClick={()=>onRemove(i)} style={{position:"absolute",top:"3px",right:"3px",background:"rgba(0,0,0,.7)",border:"none",color:"#fff",width:"18px",height:"18px",borderRadius:"2px",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>{Icons.x}</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

